mapper.select:
SELECT o.order_id, o.order_number, o.user_id, o.total_amount, o.order_status, o.payment_method, o.order_date, COUNT(DISTINCT oi.order_item_id) AS item_count, GROUP_CONCAT(DISTINCT p.product_name ORDER BY p.product_name SEPARATOR '、') AS product_names FROM orders o JOIN order_items oi ON oi.order_id = o.order_id JOIN products p ON p.product_id = oi.product_id WHERE o.deleted_at IS NULL AND p.merchant_id = #{merchantId}
AND o.order_status = #{status}
GROUP BY o.order_id ORDER BY o.order_date DESC LIMIT #{limit} OFFSET #{offset}
